import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Select as UISelect, SelectContent, SelectItem, SelectTrigger, SelectValue } from "./components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "./components/ui/card";
import { XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, BarChart, Bar, PieChart, Pie, Cell } from 'recharts';
import * as XLSX from 'xlsx';

const LTVDashboard = () => {
  const [period, setPeriod] = useState('m');
  const [data, setData] = useState({
    metrics: [],
    clientSegments: []
  });

  useEffect(() => {
    console.log('Current data state:', data);
  }, [data]);

  const COLORS = {
    segments: ['#FF8042', '#0088FE', '#00C49F'], // оранжевый, синий, зеленый
    gender: ['#4169E1', '#FF69B4'] // синий, розовый
  };

  const fileMapping = useMemo(() => ({
    m: './clients_m.xlsx',
    q: './clients_q.xlsx',
    hy: './clients_hy.xlsx',
    y: './clients_y.xlsx',
    all: './clients.xlsx'
  }), []);

  const periodLabels = useMemo(() => ({
    m: 'Месяц',
    q: 'Квартал',
    hy: 'Полгода',
    y: 'Год',
    all: 'Все время'
  }), []);

  const nameData = useMemo(async () => {
    try {
      const [femaleKzRaw, femaleRusRaw, maleKzRaw, maleRusRaw] = await Promise.all([
        fetch('./female_names_kz.txt').then(r => r.text()),
        fetch('./female_names_rus.txt').then(r => r.text()),
        fetch('./male_names_kz.txt').then(r => r.text()),
        fetch('./male_names_rus.txt').then(r => r.text())
      ]);

      const cleanNames = (raw) => new Set(raw.split('\n').map(name => name.trim().toUpperCase()).filter(Boolean));

      return {
        femaleKzNames: cleanNames(femaleKzRaw),
        femaleRusNames: cleanNames(femaleRusRaw),
        maleKzNames: cleanNames(maleKzRaw),
        maleRusNames: cleanNames(maleRusRaw)
      };
    } catch (error) {
      console.error('Error loading name data:', error);
      return {
        femaleKzNames: new Set(),
        femaleRusNames: new Set(),
        maleKzNames: new Set(),
        maleRusNames: new Set()
      };
    }
  }, []);

  const normalizeKazakhName = useCallback((name) => {
    return name
      .replace(/Ә/g, 'А')
      .replace(/І/g, 'И')
      .replace(/Ң/g, 'Н')
      .replace(/Ғ/g, 'Г')
      .replace(/Ү/g, 'У')
      .replace(/Ұ/g, 'У')
      .replace(/Қ/g, 'К')
      .replace(/Ө/g, 'О')
      .replace(/Һ/g, 'Х');
  }, []);

  const determineGender = useCallback(async (name) => {
    if (!name || typeof name !== 'string' || name.includes('Клиент')) return 'unknown';

    const cleanName = name.trim().toUpperCase();
    const normalizedName = normalizeKazakhName(cleanName);

    // Check surname endings first
    if (cleanName.endsWith('ОВА') || cleanName.endsWith('ЕВА') || cleanName.endsWith('ИНА')) return 'female';
    if (cleanName.endsWith('ОВ') || cleanName.endsWith('ЕВ') || cleanName.endsWith('ИН')) return 'male';

    const names = await nameData;
    
    // Check against name lists
    if (names.femaleKzNames.has(cleanName) || names.femaleKzNames.has(normalizedName) ||
        names.femaleRusNames.has(cleanName)) {
      return 'female';
    }
    
    if (names.maleKzNames.has(cleanName) || names.maleKzNames.has(normalizedName) ||
        names.maleRusNames.has(cleanName)) {
      return 'male';
    }

    return 'unknown';
  }, [nameData, normalizeKazakhName]);

  const calculateCustomerSegments = (jsonData) => {
    const oneTime = jsonData.filter(row => row['Заказы'] === 1).length;
    const regular = jsonData.filter(row => row['Заказы'] >= 2 && row['Заказы'] <= 3).length;
    const loyal = jsonData.filter(row => row['Заказы'] >= 4).length;
    
    return [
      { name: 'Одноразовые', value: oneTime },
      { name: 'Постоянные', value: regular },
      { name: 'Лояльные', value: loyal }
    ];
  };

  const calculateGenderDistribution = useCallback(async (jsonData) => {
    const genderPromises = jsonData.map(async row => await determineGender(row['Имя']));
    const genders = await Promise.all(genderPromises);
    
    const genderCounts = genders.reduce((acc, gender) => {
      if (gender !== 'unknown') {
        acc[gender] = (acc[gender] || 0) + 1;
      }
      return acc;
    }, {});

    return [
      { name: 'Женщины', value: genderCounts.female || 0 },
      { name: 'Мужчины', value: genderCounts.male || 0 }
    ];
  }, [determineGender]);

  const calculateGenderLTV = async (jsonData) => {
    let maleTotal = 0, maleCount = 0;
    let femaleTotal = 0, femaleCount = 0;
  
    for (const row of jsonData) {
      const gender = await determineGender(row['Имя']);
      const sum = parseFloat(row['Сумма'].toString().replace(/[^\d.-]/g, ''));
      
      console.log('Processing row:', { name: row['Имя'], gender, sum });
      
      if (!isNaN(sum)) {
        if (gender === 'male') {
          maleTotal += sum;
          maleCount++;
        } else if (gender === 'female') {
          femaleTotal += sum;
          femaleCount++;
        }
      }
    }
  
    console.log('Gender totals:', { maleTotal, maleCount, femaleTotal, femaleCount });
  
    return {
      male: (maleTotal * 0.35) / (maleCount || 1),
      female: (femaleTotal * 0.35) / (femaleCount || 1)
    };
  };
  
  const calculateSegmentLTV = (jsonData) => {
    let loyalTotal = 0, loyalCount = 0;
    let regularTotal = 0, regularCount = 0;
    let oneTimeTotal = 0, oneTimeCount = 0;
  
    console.log('Start segment calculation for quarterly data:', jsonData[0]);
  
    for (const row of jsonData) {
      const orders = parseInt(row['Заказы']);
      const sum = parseFloat(row['Сумма'].toString().replace(/[^\d.-]/g, ''));
  
      console.log(`Processing row: orders=${orders}, sum=${sum}`);
  
      if (!isNaN(sum) && !isNaN(orders)) {
        if (orders >= 4) {
          loyalTotal += sum;
          loyalCount++;
        } else if (orders >= 2) {
          regularTotal += sum;
          regularCount++;
        } else {
          oneTimeTotal += sum;
          oneTimeCount++;
        }
      }
    }
  
    console.log('Final totals:', {
      loyal: { total: loyalTotal, count: loyalCount },
      regular: { total: regularTotal, count: regularCount },
      oneTime: { total: oneTimeTotal, count: oneTimeCount }
    });
  
    return {
      loyal: loyalCount > 0 ? (loyalTotal * 0.35) / loyalCount : 0,
      regular: regularCount > 0 ? (regularTotal * 0.35) / regularCount : 0,
      oneTime: oneTimeCount > 0 ? (oneTimeTotal * 0.35) / oneTimeCount : 0
    };
  };

  const calculateRR = (jsonData) => {
    const totalClients = jsonData.length;
    const repeatClients = jsonData.filter(row => row['Заказы'] > 1).length;
    return (repeatClients / totalClients) * 100;
  };

  const loadPeriodData = useCallback(async (selectedPeriod) => {
    try {
      console.log('Loading file:', fileMapping[selectedPeriod]);
      const response = await fetch(fileMapping[selectedPeriod]);
      const arrayBuffer = await response.arrayBuffer();
      
      const workbook = XLSX.read(arrayBuffer, {
        cellDates: true,
        cellStyles: true,
        cellNF: true
      });
      
      console.log('Workbook sheets:', workbook.SheetNames);
      const sheet = workbook.Sheets[workbook.SheetNames[0]];
      const jsonData = XLSX.utils.sheet_to_json(sheet);
      console.log('Parsed data:', jsonData);
   
      if(!jsonData.length) {
        console.error('No data parsed from file');
        return;
      }
   
      const requiredColumns = ['Имя', 'Заказы', 'Сумма'];  
      const missingColumns = requiredColumns.filter(col => !jsonData[0].hasOwnProperty(col));
      
      if(missingColumns.length) {
        console.error('Missing required columns:', missingColumns);
        return;
      }
   
      const genderDistribution = await calculateGenderDistribution(jsonData);
   
      let genderLTV = { male: 0, female: 0 };
      let segmentLTV = { loyal: 0, regular: 0, oneTime: 0 };
   
      if (selectedPeriod === 'y') {
        genderLTV = await calculateGenderLTV(jsonData);
      }
   
      if (selectedPeriod === 'q') {
        segmentLTV = calculateSegmentLTV(jsonData);
      }
   
      const metrics = {
        period: periodLabels[selectedPeriod],
        avgCheck: jsonData.reduce((acc, row) => {
          const orders = Number(row['Заказы']) || 0;
          const sum = Number(row['Сумма']) || 0;
          return orders > 0 ? acc + (sum / orders) : acc;
        }, 0) / jsonData.length,
        totalOrders: jsonData.reduce((acc, row) => acc + (Number(row['Заказы']) || 0), 0),
        totalRevenue: jsonData.reduce((acc, row) => acc + (Number(row['Сумма']) || 0), 0),
        retentionRate: calculateRR(jsonData),
        segments: calculateCustomerSegments(jsonData),
        genderDistribution,
        genderLTV,
        segmentLTV
      };
   
      console.log('Calculated metrics:', metrics);
   
      setData(prev => ({
        ...prev,
        metrics: [...prev.metrics, metrics].sort((a, b) => b.ltv - a.ltv)
      }));
   
    } catch (error) {
      console.error('Error loading data:', error);
      console.error('Error stack:', error.stack);
    }
   }, [fileMapping, periodLabels, calculateGenderDistribution]);

  useEffect(() => {
    setData({ metrics: [], clientSegments: [] });
    Object.keys(fileMapping).forEach(p => loadPeriodData(p));
  }, [fileMapping, loadPeriodData]);

  return (
<div className="space-y-4 p-4">
<div className="grid grid-cols-1 gap-4">
  {/* Основной график LTV/Retention */}
  <Card className="col-span-2">
    <CardHeader>
      <CardTitle>LTV и Retention Rate</CardTitle>
      <UISelect value={period} onValueChange={setPeriod}>
        <SelectTrigger className="w-48">
          <SelectValue placeholder="Выберите период" />
        </SelectTrigger>
        <SelectContent>
          {Object.entries(periodLabels).map(([key, label]) => (
            <SelectItem key={key} value={key}>{label}</SelectItem>
          ))}
        </SelectContent>
      </UISelect>
    </CardHeader>
    <CardContent>
      <div className="h-96">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data.metrics}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="period" />
            <YAxis yAxisId="left" />
            <YAxis yAxisId="right" orientation="right" />
            <Tooltip 
              formatter={(value, name) => {
                if (name === 'Retention Rate') {
                  return `${value.toFixed(1)}%`;
                }
                return new Intl.NumberFormat('ru-KZ', {
                  style: 'currency',
                  currency: 'KZT'
                }).format(value);
              }}
            />
            <Legend />
            <Bar yAxisId="left" dataKey="avgCheck" fill="#82ca9d" name="Средний чек" />
            <Bar yAxisId="right" dataKey="retentionRate" fill="#ffc658" name="Retention Rate" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </CardContent>
  </Card>

  {/* Метрики по периодам */}
  {data.metrics.map((metric, idx) => (
    <div key={idx} className="grid grid-cols-1 lg:grid-cols-2 gap-4">
      {/* Основные метрики */}
      <Card className="lg:col-span-2">
        <CardHeader>
          <CardTitle>{metric.period} - Основные метрики</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            <p>Средний чек: {new Intl.NumberFormat('ru-KZ', {style: 'currency', currency: 'KZT'}).format(metric.avgCheck)}</p>
            <p>Retention Rate: {metric.retentionRate.toFixed(1)}%</p>
            <p>Всего заказов: {metric.totalOrders}</p>
            <p>Общая выручка: {new Intl.NumberFormat('ru-KZ', {style: 'currency', currency: 'KZT'}).format(metric.totalRevenue)}</p>
          </div>
        </CardContent>
      </Card>

      {/* LTV по полу */}
      {metric.period === periodLabels['y'] && (
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>LTV по полу</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
              // Для LTV по полу
              <BarChart data={[
  { name: 'Мужчины', value: metric.genderLTV.male },
  { name: 'Женщины', value: metric.genderLTV.female }
]}>
  <CartesianGrid strokeDasharray="3 3" />
  <XAxis dataKey="name" />
  <YAxis />
  <Tooltip formatter={(value) => new Intl.NumberFormat('ru-KZ', {
    style: 'currency',
    currency: 'KZT'
  }).format(value)}/>
  <Bar dataKey="value" fill={COLORS.gender[0]}>
    <Cell fill={COLORS.gender[0]} />
    <Cell fill={COLORS.gender[1]} />
  </Bar>
</BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      )}

      {/* LTV по сегментам */}
      {metric.period === periodLabels['q'] && (
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>LTV по сегментам</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
              <BarChart data={[
  { name: 'Одноразовые', value: metric.segmentLTV.oneTime },
  { name: 'Лояльные', value: metric.segmentLTV.loyal },
  { name: 'Постоянные', value: metric.segmentLTV.regular }
]}>
  <CartesianGrid strokeDasharray="3 3" />
  <XAxis dataKey="name" />
  <YAxis />
  <Tooltip formatter={(value) => new Intl.NumberFormat('ru-KZ', {
    style: 'currency',
    currency: 'KZT'
  }).format(value)}/>
  <Bar dataKey="value">
    <Cell fill={COLORS.segments[0]} />
    <Cell fill={COLORS.segments[1]} />
    <Cell fill={COLORS.segments[2]} />
  </Bar>
</BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Сегменты клиентов */}
      <Card>
        <CardHeader>
          <CardTitle>{metric.period} - Сегменты клиентов</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={metric.segments}
                  innerRadius={50}
                  outerRadius={70}
                  paddingAngle={5}
                  dataKey="value"
                  label={({percent}) => `${(percent * 100).toFixed(0)}%`}
                >
                  {metric.segments.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS.segments[index % COLORS.segments.length]} />
                  ))}
                </Pie>
                <Tooltip
                  formatter={(value, name) => [
                    `${value} клиентов (${((value / metric.segments.reduce((acc, curr) => acc + curr.value, 0)) * 100).toFixed(1)}%)`,
                    name
                  ]}
                />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>

      {/* Распределение по полу */}
      <Card>
        <CardHeader>
          <CardTitle>{metric.period} - Распределение по полу</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={metric.genderDistribution}
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                  label={({percent}) => `${(percent * 100).toFixed(0)}%`}
                >
                  {metric.genderDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS.gender[index % COLORS.gender.length]} />
                  ))}
                </Pie>
                <Tooltip
                  formatter={(value, name) => [
                    `${value} клиентов (${((value / metric.genderDistribution.reduce((acc, curr) => acc + curr.value, 0)) * 100).toFixed(1)}%)`,
                    name
                  ]}
                />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>
    </div>
  ))}
</div>
</div>
);
};

export default LTVDashboard;